[{"order":1,"type":"heading","text":"Authentication and Authorization in Python"},{"order":2,"type":"paragraph","text":"Authentication and authorization are crucial aspects of securing any application. Authentication verifies the identity of a user, while authorization determines what resources a user has access to. This tutorial will guide you through implementing these concepts in Python."},{"order":3,"type":"subheading","text":"Authentication"},{"order":4,"type":"paragraph","text":"Authentication is the process of verifying a user's identity. Common methods include username/password combinations, API keys, and token-based authentication."},{"order":5,"type":"code","text":"import hashlib

def hash_password(password):
    # Salt the password for added security
    salt = 'your_salt_here'  # Replace with a strong, unique salt
    salted_password = password + salt
    hashed_password = hashlib.sha256(salted_password.encode()).hexdigest()
    return hashed_password

def verify_password(password, hashed_password):
    # Hash the provided password with the same salt
    salt = 'your_salt_here'  # Use the same salt as during hashing
    salted_password = password + salt
    hashed_password_candidate = hashlib.sha256(salted_password.encode()).hexdigest()
    return hashed_password_candidate == hashed_password

# Example usage
password = 'mysecretpassword'
hashed = hash_password(password)
print(f'Hashed password: {hashed}')

if verify_password(password, hashed):
    print('Password verified!')
else:
    print('Password verification failed!')"},{"order":6,"type":"paragraph","text":"This code snippet demonstrates a basic password hashing and verification process using the 'hashlib' library.  Remember to replace 'your_salt_here' with a strong, unique salt for each application.  Storing passwords in plain text is highly discouraged."},{"order":7,"type":"subheading","text":"Authorization"},{"order":8,"type":"paragraph","text":"Authorization determines what resources an authenticated user is allowed to access. This is often implemented using roles or permissions."},{"order":9,"type":"code","text":"def check_permission(user_role, required_permission):
    # Example: Define roles and their associated permissions
    permissions = {
        'admin': ['read', 'write', 'delete'],
        'editor': ['read', 'write'],
        'viewer': ['read']
    }

    if user_role in permissions and required_permission in permissions[user_role]:
        return True
    else:
        return False

# Example usage
user_role = 'editor'
required_permission = 'write'

if check_permission(user_role, required_permission):
    print('User has permission.')
else:
    print('User does not have permission.')"},{"order":10,"type":"paragraph","text":"This example demonstrates a simple permission check based on user roles.  In a real-world application, this logic would likely be more complex and integrated with a database."},{"order":11,"type":"subheading","text":"Using Flask for Authentication and Authorization"},{"order":12,"type":"paragraph","text":"Flask is a popular Python web framework that simplifies the implementation of authentication and authorization. Libraries like Flask-Login and Flask-Principal provide helpful tools."},{"order":13,"type":"code","text":"from flask import Flask, redirect, url_for, request, session, abort

app = Flask(__name__)
app.secret_key = 'your_secret_key' # Replace with a strong, random key

users = {
    'admin': 'password',
    'user': 'password'
}

@app.route('/')
def index():
    if 'username' in session:
        return f'Logged in as {session['username']}<br><a href="/logout">Logout</a>'
    return 'You are not logged in <br><a href="/login">Login</a>'

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        if username in users and users[username] == password:
            session['username'] = username
            return redirect(url_for('index'))
        else:
            return 'Invalid credentials'
    return '''
    <form method="post">
        <p><input type=text name=username>
        <p><input type=password name=password>
        <p><input type=submit value=Login>
    </form>
    '''

@app.route('/logout')
def logout():
    session.pop('username', None)
    return redirect(url_for('index'))

@app.route('/profile')
def profile():
    if 'username' not in session:
        abort(401) # Unauthorized
    return f'Profile page for {session['username']}'

if __name__ == '__main__':
    app.run(debug=True)"},{"order":14,"type":"paragraph","text":"This Flask example demonstrates basic session-based authentication.  It includes login, logout, and a protected profile route.  Remember to replace 'your_secret_key' with a strong, random key.  Also, storing passwords directly in the code is insecure; use proper hashing as shown earlier."},{"order":15,"type":"bullet_point","text":"Always use strong, unique salts when hashing passwords."},{"order":16,"type":"bullet_point","text":"Consider using a dedicated authentication library like Flask-Login for more advanced features."},{"order":17,"type":"bullet_point","text":"Implement proper authorization checks to restrict access to sensitive resources."},{"order":18,"type":"bullet_point","text":"Store sensitive information (like API keys and database passwords) securely using environment variables or a secrets management system."},{"order":19,"type":"paragraph","text":"By following these guidelines, you can build more secure and robust Python applications."}]
